import { test, expect } from '@playwright/test';

test.describe('Snackbar Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should display snackbar message after copying text', async ({ page }) => {
    await page.getByText('Copy Text Button').click();
    const snackbar = page.getByRole('alert', { name: /copied to clipboard/i });
    await expect(snackbar).toBeVisible();
    await expect(snackbar).toHaveText('Copied to clipboard!');
  });

  test('should hide snackbar message after a timeout', async ({ page }) => {
    await page.getByText('Copy Text Button').click();
    const snackbar = page.getByRole('alert', { name: /copied to clipboard/i });
    await expect(snackbar).toBeVisible();
    await page.waitForTimeout(3000); // Assuming snackbar disappears after 3 seconds
    await expect(snackbar).not.toBeVisible();
  });
});
